import{z as r,x as o,o as B,c as d,q as l,j as s,D as a,d as t,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"随机舍入与低精度优化","description":"","frontmatter":{"title":"随机舍入与低精度优化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-stochastic-rounding.md","filePath":"llm/num-stochastic-rounding.md","lastUpdated":1791063341000}'),p={name:"llm/num-stochastic-rounding.md"};function D(m,E,c,h,C,R){const A=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=l('<h1 id="随机舍入与低精度优化" tabindex="-1">随机舍入与低精度优化 <a class="header-anchor" href="#随机舍入与低精度优化" aria-label="Permalink to &quot;随机舍入与低精度优化&quot;">​</a></h1><div class="epigraph"><p>舍入到最近是有偏的：比半格更小的更新永远落不进格子；随机舍入拿方差换无偏，让小步长在统计上活下来。</p><footer>—— 据浮点误差分析的随机舍入文献与低精度训练硬件实践整理</footer></div><p><a href="/llm/num-fp8-scaling">上一课</a>写完 FP8 的尺子，但尺子作用在最后一个环节：把真值写回存储。写回用的舍入函数默认是舍入到最近（RN），它在第一课被当成理所当然；本课打开它。RN 有系统偏置——比半格小的更新永远丢失。随机舍入（stochastic rounding, SR）是无偏的替代。本课写它的定义、适用位置，以及它与 FP32 主权重在「保住小更新」上的分工：一个花显存，一个花方差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把偏置算清楚。权重更新是 \\(\\Delta w = -\\eta g\\)。设当前权重落在格子的某处，若 \\(|\\Delta w|\\) 小于 ULP 的一半，RN 之后 \\(w\\) 原地不动——不是偶尔丢失，是<strong>只要方向与幅度不变就永远丢失</strong>。小学习率、长尾的小梯度、训练后期的精细调整，全都落在这个区间：损失停在平台上，梯度非零而权重不动。第一课的对策是主权重留在 FP32，让累积发生在细格子里；但 FP32 主权重加 FP32 动量是显存大头，窄宽度训练的动机之一恰恰是省这份钱。</p><p><span class="marginnote">数字实例：把 ULP 想成格宽 0.01。本步更新 \\(\\Delta w = -0.004\\)，不足半格（0.005），RN 之后权重原地不动——哪怕之后一万步都是同方向的小梯度，权重也一格未进；「梯度非零、损失停在平台上」说的就是这件事。</span></p><p>不均匀的格子加深问题：浮点的 ULP 随幅度变化，权重大时小更新的相对步长更小，更容易落在半格以内。偏置不随训练平均掉——它不是噪声，是确定性丢失。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SR 的定义：对真值 \\(x\\) 落在相邻格子 \\(a \\lt x \\lt b\\) 之间，以概率 \\(p = (x-a)/(b-a)\\) 舍到 \\(b\\)，否则舍到 \\(a\\)。期望 \\(E[\\mathrm{SR}(x)] = x\\)：单次有误差，累积无偏。半格以内的更新不再确定性丢失，而是以正确的概率偶尔前进一格，多次更新后期望走完该走的路。</p><p><span class="marginnote">直觉类比：SR 像在两个格点之间掷一枚不均匀的骰子——离哪个格点越近，落到它的概率越大。掷一次可能错，掷一万次后，平均位置恰好回到真值：单次有误差，累积无偏。</span></p><p>用在哪比用什么更重要。全网每个算子都做 SR 既贵又没必要：误差的入口在<strong>权重更新的写回</strong>——每次优化器 step 的最后一舍。这一舍换 SR，前向与反向的算术仍用 RN。实现要点有二：每次舍入要新的随机数，复用同一随机流会引入相关；硬件不支持的卡上用软件模拟，模拟本身要读写随机位，收益先被开销吃掉一块。支持 SR 的硬件（部分 TPU 与研究用加速器）把它做进写回路径，才是「bf16 无主权重训练」真正跑通的地方。</p>',11)),(B(),s(n,null,{default:a(()=>[i(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%A2%AF%E5%BA%A6%20g%22%5D%20--%3E%20U%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E5%9C%A8%E5%AE%BD%E6%A0%BC%E5%BC%8F%E7%AE%97%E6%9B%B4%E6%96%B0%20%CE%94w%22%5D%0A%20%20U%20--%3E%20MODE%7B%22%E5%86%99%E5%9B%9E%E8%88%8D%E5%85%A5%22%7D%0A%20%20MODE%20--%3E%7CRN%7C%20RN%5B%22%E5%B0%8F%E4%BA%8E%E5%8D%8A%E6%A0%BC%E7%9A%84%E6%9B%B4%E6%96%B0%E7%A1%AE%E5%AE%9A%E6%80%A7%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20MODE%20--%3E%7CSR%7C%20SR%5B%22%E6%8C%89%E8%B7%9D%E7%A6%BB%E6%AF%94%E4%BE%8B%E6%A6%82%E7%8E%87%E8%BF%9B%E4%BD%8D%22%5D%0A%20%20SR%20--%3E%20W%5B%22%E7%AA%84%E6%A0%BC%E5%BC%8F%E6%9D%83%E9%87%8D%22%5D%0A%20%20RN%20--%3E%20W%0A%20%20W%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%E5%89%8D%E5%90%91%E4%BB%8D%E7%94%A8%20RN%20%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"无偏不等于无害：SR 把偏置换成方差，方差进入权重轨迹，等效于给训练加了一层温度。大 batch 与长训练把方差平均掉，期望意义上更新正确积累——这与 BF16 靠大 batch 平均更新噪声是同一机制，只是换了位置。对照主权重方案：FP32 主权重是「用显存买零偏置零方差」，SR 是「用方差买零偏置」。优化器状态不在交换之列：Adam 的二阶矩 \\(v\\) 对噪声平方敏感，窄格式存 \\(v\\) 会把步长估计带偏，动量与 \\(v\\) 仍应留在宽格式——SR 只豁免权重本体。",-1)),(B(),s(n,null,{default:a(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E5%85%B1%E5%90%8C%E7%9B%AE%E6%A0%87%EF%BC%9A%E4%BF%9D%E4%BD%8F%E5%8D%8A%E6%A0%BC%E4%BB%A5%E5%86%85%E7%9A%84%E5%B0%8F%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20A%5B%22%E6%96%B9%E6%A1%88%E4%B8%80%EF%BC%9AFP32%20%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%0A%20%20GOAL%20--%3E%20B%5B%22%E6%96%B9%E6%A1%88%E4%BA%8C%EF%BC%9A%E9%9A%8F%E6%9C%BA%E8%88%8D%E5%85%A5%20SR%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%98%BE%E5%AD%98%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%81%8F%E7%BD%AE%200%EF%BC%8C%E6%96%B9%E5%B7%AE%200%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%96%B9%E5%B7%AE%EF%BC%88%E8%AE%AD%E7%BB%83%E6%B8%A9%E5%BA%A6%E5%8D%87%E9%AB%98%EF%BC%89%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%81%8F%E7%BD%AE%200%EF%BC%8C%E6%96%B9%E5%B7%AE%E9%9D%A0%E5%A4%A7%20batch%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E7%8A%B6%E6%80%81%E4%BB%8D%E7%95%99%E5%AE%BD%E6%A0%BC%E5%BC%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">SR 与下一课的 STE 是两种不同的偏置来源：STE 是梯度方向的偏置（取整导数几乎处处为零，直通是估计），SR 是写回舍入的偏置。混在一起说「训练噪声」会归因错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SR 治写回，不治累加：长归约的截断误差仍要宽累加器，别指望随机舍入救 softmax。推理不需要 SR——没有更新就没有偏置可消。方差不是免费：极小 batch、超长尾的损失或对温度敏感的微调里，方差本身会伤质量，此时主权重方案更稳。最后，SR 的收益 claim 要有对照实验：同宽格式、同 schedule，开与关 SR 对比小学习率段的平台现象——「开了 SR 更稳」若没有 FP32 主权重参照轨，分不清是 SR 的功劳还是别处变了。</p><p><span class="marginnote">常见误区：把「无偏」听成「没有代价」。SR 只是把确定性偏置换成了随机方差，权重轨迹因此多一层温度；极小 batch 或温度敏感的微调里方差平均不掉，质量反而受损——这时该回到 FP32 主权重，用显存把方差也买掉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RN 舍入对小更新有确定性偏置：半格以内的更新永远丢失，表现为损失平台。</li><li>SR 按距离比例概率进位，期望无偏，用方差换偏置；大 batch 与长训练平均掉方差。</li><li>用在优化器写回这一舍最有效；前向计算仍用 RN。</li><li>优化器状态不豁免：动量与二阶矩留在宽格式。</li><li>与 FP32 主权重的分工：一个花显存，一个花方差；两者都为保住小更新。</li><li>出处：浮点误差分析的随机舍入文献与低精度硬件实践；混合精度主权重口径见 Micikevicius et al., 2018。</li></ul>',6))])}const F=r(p,[["render",D]]);export{u as __pageData,F as default};
